export const SEGS: Seg[] = [{"spk": "valentino", "text": "Muy buenas tardes a toda la comunidad que nos sigue a esta hora en vivo.", "start": 5.0, "end": 8.067, "block": 1}, {"spk": "valentino", "text": "Son las 16:00 horas y estamos en cobertura urgente por la erupción del volcán Chaitén, en la Región de los Lagos, en una jornada marcada por ceniza, evacuaciones, riesgo de lahares,", "start": 8.367, "end": 18.755, "block": 1}, {"spk": "valentino", "text": "cortes de caminos y sectores aislados.", "start": 19.055, "end": 21.316, "block": 1}, {"spk": "valentino", "text": "Hoy revisamos cómo se distribuyeron los 100 créditos disponibles y qué decisiones se tomaron en terreno.", "start": 21.616, "end": 27.539, "block": 1}, {"spk": "valentino", "text": "A las 05:40, SERNAGEOMIN informó un aumento abrupto de la actividad sísmica del volcán y llamó a preparar evacuación y alejarse de cauces y zonas de peligro.", "start": 28.439, "end": 37.628, "block": 2}, {"spk": "valentino", "text": "A las 07:10 comenzó una emisión importante de ceniza: cambió el viento, la nube avanzó sobre sectores habitados, bajó la visibilidad y la ceniza se acumuló en calles y techumbres.", "start": 37.928, "end": 49.366, "block": 2}, {"spk": "valentino", "text": "A las 08:00 se ordenó la evacuación preventiva de sectores expuestos, aunque parte de la población demoró en salir por reunir documentos, medicamentos, pertenencias o mascotas.", "start": 49.666, "end": 59.452, "block": 2}, {"spk": "valentino", "text": "A las 09:20 la caída de ceniza afectó caminos, sistemas de agua y servicios básicos, dejando dos caminos secundarios inutilizados para vehículos chicos.", "start": 59.752, "end": 68.597, "block": 2}, {"spk": "valentino", "text": "A las 10:30 llegaron al centro de salud personas con dificultades respiratorias y se reportaron adultos mayores y personas con movilidad reducida sin desplazamiento autónomo.", "start": 68.897, "end": 83.025, "block": 2}, {"spk": "valentino", "text": "A las 11:40 vecinos avisaron de mascotas dentro de casas y familias que querían volver a buscarlas pese a la orden de evacuar.", "start": 83.325, "end": 89.486, "block": 2}, {"spk": "valentino", "text": "Al mediodía, a las 12:00, hubo una explosión mayor, alerta de lahares por cauces y quebradas, y una ruta principal quedó parcialmente bloqueada.", "start": 89.786, "end": 97.804, "block": 2}, {"spk": "valentino", "text": "A las 14:00 salud indicó que necesitaba mantener agua y electricidad para seguir operando, y bomberos recibió llamados para reingresar a zonas evacuadas.", "start": 98.104, "end": 107.402, "block": 2}, {"spk": "valentino", "text": "Finalmente, a las 16:00, el albergue empezó a quedarse sin capacidad suficiente, mientras persistían personas aisladas", "start": 107.702, "end": 114.375, "block": 2}, {"spk": "valentino", "text": "—incluida una familia aislada en un sector rural—, mascotas en viviendas y una ruta crítica sin despejar.", "start": 114.675, "end": 120.215, "block": 2}, {"spk": "valentino", "text": "Transición en vivo hacia los despachos y entrevistas con los voceros del comité en terreno.", "start": 124.115, "end": 128.243, "block": 3}, {"spk": "valentino", "text": "Estamos en vivo con Rashid, alcalde y encargado de emergencias.", "start": 129.143, "end": 132.562, "block": 4}, {"spk": "valentino", "text": "Alcalde, ¿por qué decidieron evacuar determinados sectores y no otros, qué criterios usaron para priorizar, y por qué se eligió evacuar un sector residencial, habilitar punto de encuentro,", "start": 132.862, "end": 142.882, "block": 4}, {"spk": "valentino", "text": "comunicar alerta a la población y trasladar población vulnerable, sin decidir apoyar la evacuación de personas con movilidad reducida ni rescatar mascotas y animales domésticos?", "start": 143.182, "end": 152.336, "block": 4}, {"spk": "rashid", "text": "Gracias, Valentino.", "start": 152.886, "end": 154.272, "block": 4}, {"spk": "rashid", "text": "Priorizamos según la exposición directa a la amenaza volcánica y la geografía del territorio:", "start": 154.572, "end": 159.725, "block": 4}, {"spk": "rashid", "text": "primero la sismicidad de las 05:40, luego la nube de ceniza y baja visibilidad desde las 07:10 y, a las 12:00, la explosión mayor con riesgo de lahares en cauces y quebradas.", "start": 160.025, "end": 173.558, "block": 4}, {"spk": "rashid", "text": "Decidimos comunicar alerta a la población para entregar instrucciones claras y advertir zonas peligrosas, y evacuar un sector residencial hacia una zona segura.", "start": 173.858, "end": 184.275, "block": 4}, {"spk": "rashid", "text": "Sumamos habilitar punto de encuentro para reunir y contabilizar a quienes evacuaban, y trasladar población vulnerable para sacar rápido a quienes estaban más expuestos en sectores de riesgo.", "start": 184.575, "end": 196.869, "block": 4}, {"spk": "valentino", "text": "¿Y por qué no se decidió apoyar la evacuación de personas con movilidad reducida ni rescatar mascotas y animales domésticos, considerando los avisos de las 08:00, 10:30 y 11:40?", "start": 197.419, "end": 208.614, "block": 4}, {"spk": "rashid", "text": "No se decidió rescatar mascotas y animales domésticos porque con ceniza, explosión mayor desde las 12:00, riesgo de lahares y gente queriendo reingresar a zonas evacuadas a las 14:00,", "start": 209.164, "end": 219.193, "block": 4}, {"spk": "rashid", "text": "enviar personal a buscar animales suponía exponer equipos innecesariamente.", "start": 219.493, "end": 223.781, "block": 4}, {"spk": "rashid", "text": "En cuanto a apoyar la evacuación de personas con movilidad reducida, optamos por concentrar ese esfuerzo dentro de trasladar población vulnerable para no restar créditos a otras medidas críticas.", "start": 224.081, "end": 234.42, "block": 4}, {"spk": "valentino", "text": "Pasamos con Maximiliano, jefe de bomberos.", "start": 236.22, "end": 238.352, "block": 5}, {"spk": "valentino", "text": "¿Por qué concentraron sus recursos en determinados lugares, qué rescates tuvieron que priorizar, y por qué se decidió desplegar bomberos en zona crítica,", "start": 238.652, "end": 247.424, "block": 5}, {"spk": "valentino", "text": "pero no se decidió rescatar personas aisladas ni rescatar mascotas y animales domésticos?", "start": 247.724, "end": 252.68, "block": 5}, {"spk": "maximiliano", "text": "Hola, Valentino, buenas tardes a todos.", "start": 253.23, "end": 255.31, "block": 5}, {"spk": "maximiliano", "text": "Concentramos fuerzas en la zona crítica por la baja visibilidad y acumulación de ceniza desde las 07:10, la explosión y posible descenso de lahares por cauces y quebradas desde las 12:00,", "start": 255.61, "end": 265.973, "block": 5}, {"spk": "maximiliano", "text": "y los llamados de personas que querían reingresar a zonas evacuadas a las 14:00.", "start": 266.273, "end": 271.482, "block": 5}, {"spk": "maximiliano", "text": "Desplegar bomberos en zona crítica permitió enfocar rescate, protección y control en un área prioritaria.", "start": 271.782, "end": 277.682, "block": 5}, {"spk": "valentino", "text": "¿Y qué explica que no se decidiera rescatar personas aisladas —pese a haber personas aisladas y una familia aislada en un sector rural— ni rescatar mascotas y animales domésticos?", "start": 278.232, "end": 287.463, "block": 5}, {"spk": "maximiliano", "text": "No se decidió rescatar personas aisladas porque llegar a puntos aislados requería equipos y transporte en medio de caminos afectados por ceniza desde las 09:20,", "start": 288.013, "end": 296.601, "block": 5}, {"spk": "maximiliano", "text": "dos caminos secundarios inutilizados para vehículos chicos, una ruta principal bloqueada al mediodía y una ruta crítica aún sin despejar a las 16:00,", "start": 296.901, "end": 305.19, "block": 5}, {"spk": "maximiliano", "text": "lo que exponía a nuestros equipos a quedar atrapados.", "start": 305.49, "end": 310.18, "block": 5}, {"spk": "maximiliano", "text": "Y no se decidió rescatar mascotas y animales domésticos porque la medida solo aplica si las condiciones permiten hacerlo sin exponer innecesariamente al personal, algo que no se daba con explosión,", "start": 310.48, "end": 320.08, "block": 5}, {"spk": "maximiliano", "text": "ceniza y reingresos no autorizados.", "start": 320.38, "end": 322.499, "block": 5}, {"spk": "valentino", "text": "Conversamos con Nicolás, encargado de salud.", "start": 324.299, "end": 326.329, "block": 6}, {"spk": "valentino", "text": "¿Qué ocurre si perdemos agua, electricidad o acceso, qué población debía recibir atención prioritaria, y por qué se eligió restablecer agua potable y desplegar personal de salud,", "start": 326.629, "end": 337.249, "block": 6}, {"spk": "valentino", "text": "sin decidir proteger el hospital o CESFAM ni restablecer la electricidad?", "start": 337.549, "end": 341.505, "block": 6}, {"spk": "nicolas", "text": "Gracias, Valentino.", "start": 342.055, "end": 342.966, "block": 6}, {"spk": "nicolas", "text": "Si perdemos agua, se comprometen la higiene, la descontaminación y la operación básica del recinto; si perdemos electricidad, fallan equipos, iluminación y respaldo;", "start": 343.266, "end": 353.452, "block": 6}, {"spk": "nicolas", "text": "y si perdemos acceso, no llegan pacientes ni insumos.", "start": 353.752, "end": 357.875, "block": 6}, {"spk": "nicolas", "text": "La población prioritaria son quienes presentan cuadros agudos —como dificultades respiratorias por ceniza desde las 10:30— y los grupos vulnerables o dependientes.", "start": 358.175, "end": 366.771, "block": 6}, {"spk": "nicolas", "text": "Por eso se decidió desplegar personal de salud para ampliar la atención en terreno y restablecer agua potable para sostener el agua de la población y los servicios esenciales,", "start": 367.071, "end": 376.94, "block": 6}, {"spk": "nicolas", "text": "tanto tras la afectación de las 09:20 como ante el aviso de las 14:00 y la actualización.", "start": 377.24, "end": 382.673, "block": 6}, {"spk": "valentino", "text": "¿Y por qué no se decidió proteger el hospital o CESFAM ni restablecer la electricidad, aun cuando a las 14:00 se advirtió la necesidad de mantener agua y electricidad?", "start": 383.223, "end": 393.993, "block": 6}, {"spk": "nicolas", "text": "Porque con un presupuesto acotado priorizamos restablecer agua potable y desplegar personal de salud como base sanitaria inmediata,", "start": 394.543, "end": 402.23, "block": 6}, {"spk": "nicolas", "text": "sin destinar otros 35 créditos conjuntos a proteger el hospital o CESFAM ni a restablecer la electricidad.", "start": 402.53, "end": 409.021, "block": 6}, {"spk": "valentino", "text": "Cerramos con Rafael, encargado de emergencias y jefe de Carabineros.", "start": 410.821, "end": 414.482, "block": 7}, {"spk": "valentino", "text": "Con los 100 de 100 créditos utilizados y 0 créditos restantes, ¿cómo distribuyeron los recursos disponibles, qué necesidad tuvieron que postergar, y por qué no se decidió habilitar un albergue,", "start": 414.782, "end": 425.338, "block": 7}, {"spk": "valentino", "text": "restablecer el camino principal ni proteger infraestructura crítica?", "start": 425.638, "end": 429.192, "block": 7}, {"spk": "rafael", "text": "Buenas tardes, Valentino.", "start": 429.742, "end": 431.785, "block": 7}, {"spk": "rafael", "text": "Los 100 créditos se distribuyeron en evacuar un sector residencial, desplegar bomberos en zona crítica, restablecer agua potable, desplegar personal de salud, habilitar punto de encuentro,", "start": 432.085, "end": 443.659, "block": 7}, {"spk": "rafael", "text": "comunicar alerta a la población y trasladar población vulnerable.", "start": 443.959, "end": 447.111, "block": 7}, {"spk": "rafael", "text": "Tuvimos que postergar la conectividad vial y la ampliación de refugio formal, sabiendo que a las 16:00 el albergue comenzaba a quedar sin capacidad suficiente,", "start": 447.411, "end": 455.835, "block": 7}, {"spk": "rafael", "text": "había personas aisladas y una ruta crítica seguía sin despejar.", "start": 456.135, "end": 460.716, "block": 7}, {"spk": "valentino", "text": "¿Por qué no se decidió habilitar un albergue, restablecer el camino principal ni proteger infraestructura crítica?", "start": 461.266, "end": 469.047, "block": 7}, {"spk": "rafael", "text": "Porque el límite era de 100 créditos.", "start": 469.597, "end": 472.532, "block": 7}, {"spk": "rafael", "text": "No se decidió habilitar un albergue para priorizar alerta, evacuación, punto de encuentro, agua y salud;", "start": 472.832, "end": 480.165, "block": 7}, {"spk": "rafael", "text": "no se decidió restablecer el camino principal porque movilizar maquinaria y personal en una vía crítica resultaba altamente complejo con ceniza, la explosión de las 12:00 y riesgo de lahares;", "start": 480.465, "end": 490.301, "block": 7}, {"spk": "rafael", "text": "y no se decidió proteger infraestructura crítica porque esos créditos ya estaban asignados a las prioridades seleccionadas.", "start": 490.601, "end": 496.574, "block": 7}, {"spk": "valentino", "text": "Regreso al estudio central.", "start": 500.474, "end": 501.668, "block": 8}, {"spk": "valentino", "text": "En síntesis, la erupción del volcán Chaitén obligó a este comité a usar los 100 créditos en alerta, evacuación, punto de encuentro, traslado de población vulnerable,", "start": 502.568, "end": 512.567, "block": 9}, {"spk": "valentino", "text": "despliegue de bomberos en zona crítica, despliegue de salud y agua potable.", "start": 512.867, "end": 516.882, "block": 9}, {"spk": "valentino", "text": "Quedaron fuera por presupuesto y condiciones de riesgo medidas como habilitar un albergue, rescatar personas aisladas, proteger el hospital o CESFAM, restablecer camino principal,", "start": 517.182, "end": 527.008, "block": 9}, {"spk": "valentino", "text": "restablecer electricidad, apoyar la evacuación de personas con movilidad reducida, proteger infraestructura crítica y rescatar mascotas y animales domésticos,", "start": 527.308, "end": 535.995, "block": 9}, {"spk": "valentino", "text": "dejando desafíos abiertos a las 16:00 en cupo de albergue, personas aisladas, ruta crítica y agua para salud.", "start": 536.295, "end": 542.901, "block": 9}, {"spk": "valentino", "text": "Es clave la responsabilidad gubernamental para coordinar recursos y despejar riesgos, y la responsabilidad civil de respetar alertas, evacuar a tiempo y no reingresar a zonas peligrosas.", "start": 543.201, "end": 553.208, "block": 9}, {"spk": "valentino", "text": "Muchas gracias por acompañarnos en esta transmisión en vivo.", "start": 553.508, "end": 557.697, "block": 9}];
